import {commands,samplePath} from './brand-shapes.js';
const host=document.querySelector('#sculpture'),control=document.querySelector('#motionToggle');const canvas=document.createElement('canvas'),ctx=canvas.getContext('2d',{alpha:true});host.append(canvas);host.classList.add('loaded');control.hidden=false;
const shapes=commands.map(p=>({id:p.id,points:samplePath(p.commands,4)}));let paused=matchMedia('(prefers-reduced-motion: reduce)').matches,visible=true,dark=host.dataset.finish==='obsidian',phase=0,last=0,raf=0,mx=0,my=0,tx=0,ty=0,amount=0,amountTarget=0;const coarse=matchMedia('(pointer: coarse)').matches;const size={w:0,h:0};
function rotate([x,y,z]){const a=-.07+Math.sin(phase*.4)*.055+my*.1,b=.12+Math.sin(phase*.3)*.13+mx*.22,c=-.035+Math.sin(phase*.27)*.035;const yy=y*Math.cos(a)-z*Math.sin(a),zz=y*Math.sin(a)+z*Math.cos(a),xx=x*Math.cos(b)+zz*Math.sin(b);return[xx*Math.cos(c)-yy*Math.sin(c),xx*Math.sin(c)+yy*Math.cos(c)+Math.sin(phase*.6)*.045,-x*Math.sin(b)+zz*Math.cos(b)]}
function project(p){const s=Math.min(size.w,size.h)*(size.w<500?.213:.225),d=5/(5-p[2]);return[size.w*.51+p[0]*s*d,size.h*(size.w<500?.39:.45)-p[1]*s*d]}
function polygon(p,fill){ctx.fillStyle=fill;ctx.beginPath();p.forEach((v,i)=>{const q=project(v);i?ctx.lineTo(...q):ctx.moveTo(...q)});ctx.closePath();ctx.fill()}
function vertex(x,y,z,id){const o=id===1?[.24,.18,.15]:id===2?[-.24,-.18,-.1]:[0,0,.45];return rotate([x+o[0]*amount,y+o[1]*amount,z+o[2]*amount])}
function draw(){if(!size.w||!size.h)return;ctx.clearRect(0,0,size.w,size.h);const faces=[];for(const part of shapes){const shape=part.points;const front=shape.map(([x,y])=>vertex(x,y,.085,part.id)),back=shape.map(([x,y])=>vertex(x,y,-.085,part.id));for(let i=0;i<shape.length;i++){const j=(i+1)%shape.length,p=[back[i],back[j],front[j],front[i]],dx=shape[j][0]-shape[i][0],dy=shape[j][1]-shape[i][1];const l=Math.hypot(dx,dy)||1;const light=Math.max(0,dy/l*-.4-dx/l*.7);const v=(dark?20:45)+light*(dark?55:95);faces.push({p,z:p.reduce((a,v)=>a+v[2],0)/4,fill:`rgb(${v},${v},${v})`})}const g=ctx.createLinearGradient(size.w*(.08+Math.sin(phase*.45)*.06),size.h*.08,size.w*(.86+Math.sin(phase*.45)*.05),size.h*.85);if(dark){g.addColorStop(0,'#242424');g.addColorStop(.3,'#989898');g.addColorStop(.46,'#343434');g.addColorStop(.72,'#555');g.addColorStop(1,'#171717')}else{g.addColorStop(0,'#aaa');g.addColorStop(.27,'#f6f6f6');g.addColorStop(.43,'#c8c8c8');g.addColorStop(.6,'#eee');g.addColorStop(.86,'#999');g.addColorStop(1,'#ddd')}faces.push({p:front,z:front.reduce((a,v)=>a+v[2],0)/front.length,fill:g,front:true})}faces.sort((a,b)=>a.z-b.z);for(const f of faces){polygon(f.p,f.fill);if(f.front){ctx.strokeStyle=dark?'#ffffff20':'#ffffff70';ctx.lineWidth=.8;ctx.stroke()}}}
function tick(t){const dt=last?Math.min(.06,(t-last)/1000):.016;if(coarse&&dt<.03){raf=requestAnimationFrame(tick);return}last=t;const blend=1-Math.exp(-dt*7);phase+=dt;mx+=(tx-mx)*blend;my+=(ty-my)*blend;amount+=(amountTarget-amount)*blend;draw();if(!paused&&visible&&!document.hidden)raf=requestAnimationFrame(tick)}function run(){cancelAnimationFrame(raf);last=performance.now();draw();if(!paused&&visible&&!document.hidden)raf=requestAnimationFrame(tick)}function update(){control.replaceChildren(lumeIcon(paused?'play':'pause'));control.setAttribute('aria-pressed',String(paused));control.setAttribute('aria-label',paused?'Ativar movimento 3D':'Pausar movimento 3D')}
host.addEventListener('lume-explore',e=>{amountTarget=e.detail?1:0;if(paused){amount=amountTarget;draw()}else run()});control.addEventListener('click',()=>{paused=!paused;update();run()});host.addEventListener('lume-finish',e=>{dark=e.detail==='obsidian';draw()});host.addEventListener('pointermove',e=>{if(paused||e.pointerType==='touch')return;const r=host.getBoundingClientRect();tx=(e.clientX-r.left)/r.width*2-1;ty=(e.clientY-r.top)/r.height*2-1});host.addEventListener('pointerleave',()=>{tx=ty=0});const ro=new ResizeObserver(()=>{size.w=host.clientWidth;size.h=host.clientHeight;const d=Math.min(devicePixelRatio,1.7);canvas.width=size.w*d;canvas.height=size.h*d;canvas.style.width=size.w+'px';canvas.style.height=size.h+'px';ctx.setTransform(d,0,0,d,0,0);run()});ro.observe(host);const io=new IntersectionObserver(es=>{visible=es[0].isIntersecting;run()});io.observe(host);document.addEventListener('visibilitychange',run);matchMedia('(prefers-reduced-motion: reduce)').addEventListener('change',e=>{paused=e.matches;update();run()});update();addEventListener('pagehide',e=>{if(!e.persisted){cancelAnimationFrame(raf);ro.disconnect();io.disconnect()}},{once:true});
